svg.script:
(function() {
		var selR = -1, selC = -1;
		var seconds = 0;
		var timerInterval = null;

		function formatTime(s) {
			var m = Math.floor(s / 60);
			var sec = s % 60;
			return (m < 10 ? '0' + m : m) + ':' + (sec < 10 ? '0' + sec : sec);
		}

		function startTimer() {
			if (!timerInterval) {
				timerInterval = setInterval(function() {
					seconds++;
					var timerEl = document.getElementById('svg-timer');
					if (timerEl) timerEl.textContent = formatTime(seconds);
				}, 1000);
			}
		}
		startTimer();

		function highlightBoard() {
			var targetVal = (selR >= 0 && selC >= 0) ? document.getElementById('cell-' + selR + '-' + selC).getAttribute('data-val') : '0';

			for (var r = 0; r < 9; r++) {
				for (var c = 0; c < 9; c++) {
					var cell = document.getElementById('cell-' + r + '-' + c);
					var rect = document.getElementById('rect-' + r + '-' + c);
					var defaultBg = ((Math.floor(r/3) + Math.floor(c/3)) % 2 === 1) ? '#111827' : '#0d1322';
					var val = cell.getAttribute('data-val');

					if (r === selR && c === selC) {
						rect.setAttribute('fill', 'rgba(99, 102, 241, 0.45)');
						rect.setAttribute('stroke', '#818cf8');
						rect.setAttribute('stroke-width', '2');
					} else if (selR >= 0 && (r === selR || c === selC || (Math.floor(r/3) === Math.floor(selR/3) && Math.floor(c/3) === Math.floor(selC/3)))) {
						rect.setAttribute('fill', 'rgba(99, 102, 241, 0.18)');
						rect.setAttribute('stroke', '#1f293d');
						rect.setAttribute('stroke-width', '1');
					} else if (targetVal !== '0' && val === targetVal) {
						rect.setAttribute('fill', 'rgba(168, 85, 247, 0.25)');
						rect.setAttribute('stroke', '#a855f7');
						rect.setAttribute('stroke-width', '1.5');
					} else {
						rect.setAttribute('fill', defaultBg);
						rect.setAttribute('stroke', '#1f293d');
						rect.setAttribute('stroke-width', '1');
					}
				}
			}
		}

		window.undokuSelectCell = function(r, c) {
			selR = r;
			selC = c;
			highlightBoard();
		};

		window.undokuInputDigit = function(num) {
			if (selR < 0 || selC < 0) return;
			var cell = document.getElementById('cell-' + selR + '-' + selC);
			if (cell.getAttribute('data-given') === 'true') return;

			cell.setAttribute('data-val', num.toString());
			var text = document.getElementById('text-' + selR + '-' + selC);
			text.textContent = num.toString();
			text.classList.remove('text-error');

			highlightBoard();
			checkWinCondition();
		};

		window.undokuErase = function() {
			if (selR < 0 || selC < 0) return;
			var cell = document.getElementById('cell-' + selR + '-' + selC);
			if (cell.getAttribute('data-given') === 'true') return;

			cell.setAttribute('data-val', '0');
			var text = document.getElementById('text-' + selR + '-' + selC);
			text.textContent = '';
			text.classList.remove('text-error');

			highlightBoard();
		};

		window.undokuHint = function() {
			if (selR < 0 || selC < 0) return;
			var cell = document.getElementById('cell-' + selR + '-' + selC);
			if (cell.getAttribute('data-given') === 'true') return;

			var sol = cell.getAttribute('data-sol');
			window.undokuInputDigit(parseInt(sol, 10));
		};

		window.undokuReset = function() {
			for (var r = 0; r < 9; r++) {
				for (var c = 0; c < 9; c++) {
					var cell = document.getElementById('cell-' + r + '-' + c);
					if (cell.getAttribute('data-given') !== 'true') {
						cell.setAttribute('data-val', '0');
						var text = document.getElementById('text-' + r + '-' + c);
						text.textContent = '';
						text.classList.remove('text-error');
					}
				}
			}
			highlightBoard();
		};

		function checkWinCondition() {
			var filled = 0;
			var correct = 0;
			for (var r = 0; r < 9; r++) {
				for (var c = 0; c < 9; c++) {
					var cell = document.getElementById('cell-' + r + '-' + c);
					var val = cell.getAttribute('data-val');
					var sol = cell.getAttribute('data-sol');
					if (val !== '0') filled++;
					if (val === sol) correct++;
				}
			}
			if (filled === 81 && correct === 81) {
				var banner = document.getElementById('svg-status-banner');
				if (banner) banner.setAttribute('display', 'block');
				if (timerInterval) clearInterval(timerInterval);
			}
		}

		document.addEventListener('keydown', function(e) {
			if (selR < 0 || selC < 0) return;
			if (e.key >= '1' && e.key <= '9') {
				window.undokuInputDigit(parseInt(e.key, 10));
			} else if (e.key === 'Backspace' || e.key === 'Delete' || e.key === '0') {
				window.undokuErase();
			} else if (e.key === 'ArrowUp') {
				selR = (selR + 8) % 9;
				highlightBoard();
			} else if (e.key === 'ArrowDown') {
				selR = (selR + 1) % 9;
				highlightBoard();
			} else if (e.key === 'ArrowLeft') {
				selC = (selC + 8) % 9;
				highlightBoard();
			} else if (e.key === 'ArrowRight') {
				selC = (selC + 1) % 9;
				highlightBoard();
			}
		});
	})();
